def f1(x, y):
    s = x + y
    return (s * (s + 1)) // 2 + x

def f2(x, y):
    s = x + y
    return (s * (s + 1)) // 2 + y

def f3(x, y):
    return x + y

M = 4
N1 = 0
N2 = 0
N3 = 0

for x in range(M):
    for y in range(M):
        if f1(x, y) % 2 == 1:
            N1 += 1
        if f2(x, y) % 2 == 1:
            N2 += 1
        if f3(x, y) % 2 == 1:
            N3 += 1

print(f"f1 parity count (M={M}): N1 = {N1}")
print(f"f2 parity count (M={M}): N2 = {N2}")
print(f"f3 parity count (M={M}): N3 = {N3}")

